import React from "react";

export default function FormLayout({ title, children }) {
  return (
    <div
      style={{
        minHeight: "100vh",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "#3b82f6",
        padding: "40px",
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: "60px",
        }}
      >
        {/* LEFT WHITE CARD */}
        <div
          style={{
            background: "#fff",
            padding: "35px",
            width: "380px",
            borderRadius: "12px",
            boxShadow: "0 6px 16px rgba(0,0,0,0.15)",
          }}
        >
          <h2
            style={{
              marginBottom: "20px",
              fontSize: "24px",
              fontWeight: "600",
              color: "#111",
            }}
          >
            {title}
          </h2>

          {children}
        </div>

        {/* RIGHT SIDE BIG TEXT */}
        <h1
          style={{
            fontSize: "50px",
            fontWeight: "700",
            color: "white",
            lineHeight: "1.1",
            width: "320px",
          }}
        >
          Beautiful<br />Sign up<br />Form
        </h1>
      </div>
    </div>
  );
}
